import{_ as t,o,c as a,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"title":"Introduction"},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1787242450000}'),i={name:"guide/introduction.md"};function n(s,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>NetLens is a Dockerized packaging of <strong>NfSen 1.3.6p1</strong> and <strong>NfDump 1.6.17</strong>. It receives NetFlow traffic from network devices, writes flow files to local storage, and exposes the NfSen web interface on port <code>8070</code>.</p><h2 id="the-operating-model" tabindex="-1">The operating model <a class="header-anchor" href="#the-operating-model" aria-label="Permalink to &quot;The operating model&quot;">​</a></h2><ul><li>Routers export NetFlow v5, v9, or IPFIX over UDP.</li><li>The NetLens container captures each source with <code>nfcapd</code>.</li><li>NfSen creates RRD graphs and traffic summaries.</li><li>The Web UI provides profiles, graphs, Top-N views, and retention controls.</li></ul><div class="tip custom-block"><p class="custom-block-title">One writer</p><p>Keep NfSen writing to local bind-mounted folders on the NetLens host. When integrating LibreNMS, share only the data folders read-only and never run a second NfSen writer against the same live data.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Follow <a href="/guide/installation.html">Installation</a>.</li><li>Review <a href="/guide/data-folders.html">Data Folders &amp; Bind Mounts</a>.</li><li>Add your first exporter using <a href="/guide/router-sources.html">Managing Router Sources</a>.</li></ol>',7)])])}const f=t(i,[["render",n]]);export{h as __pageData,f as default};
